  Ltac shell_intros :=
    intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m l r n lo
           A2 N0 LL LR B1 F1 B2 F2 ACC1 ACC2 SV1 SV2 ST0 CEIL LO MI AC N40 INM1 INM2 DJ1 DJ2;
    acb;
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof (bv_unsigned_in_range 64 a0) as A0R; unfold bv_modulus in A0R; change (2 ^ Z.of_N 64) with (2^64) in A0R;
    pose proof (bv_unsigned_in_range 64 a1) as A1R; unfold bv_modulus in A1R; change (2 ^ Z.of_N 64) with (2^64) in A1R;
    assert (NA2 : bv_unsigned a2 = n) by (subst a2; apply unsigned_lit; lia);
    assert (LB1 : Z.of_nat (length (map b8 l)) = n) by (rewrite length_map; exact LL);
    assert (LB2 : Z.of_nat (length (map b8 r)) = n) by (rewrite length_map; exact LR);
    pose proof INM1 as INM1'; unfold in_app_mem, AHI_LO, AAPP_HI in INM1'; rewrite ASHADOW_BASE_val in INM1';
    pose proof INM2 as INM2'; unfold in_app_mem, AHI_LO, AAPP_HI in INM2'; rewrite ASHADOW_BASE_val in INM2';
    assert (SRV : 2147450880 <= sh (hull_lo (bv_unsigned a0)) /\ sh (hull_hi (bv_unsigned a0 + n)) <= 17594333495296 + 16
                  /\ 2147450880 <= sh (hull_lo (bv_unsigned a1)) /\ sh (hull_hi (bv_unsigned a1 + n)) <= 17594333495296 + 16)
      by (unfold sh, hull_lo, hull_hi; rewrite ASHADOW_BASE_val; Z.div_mod_to_equations; lia);
    pose proof (bytes_at_bound _ _ _ _ B1) as SB1; rewrite length_map in SB1;
    pose proof (bytes_at_bound _ _ _ _ B2) as SB2; rewrite length_map in SB2;
    assert (C5 : rw_cells asegs m AINITED_CELL [C1 (b8 1); C1 (b8 1)]) by (eapply ACONST_cell; [exact AC | cbn; tauto]);
    unfold AINITED_CELL in C5; change (b8 1) with (Z_to_bv 8 1) in C5;
    pose proof (wmono_refl asegs m) as WM;
    pose proof SV1 as SV1m; unfold shvis in SV1m; pose proof SV2 as SV2m; unfold shvis in SV2m.

  (* [comment removed for export] *)
  Ltac shell_consts :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch goal with MU : munch ?W ?m0 mx, WM : wmono _ ?m0 mx, AC : ACONST ?m0 |- _ =>
        assert (ACm : ACONST mx)
          by (eapply ACONST_frame; [exact AC | exact MU | exact WM |];
              constructor; [|constructor];
              apply aconst_ok_high; cbn [fst snd]; unfold sh, AIMG_TOP; rewrite ?ASHADOW_BASE_val; lia) end;
      lazymatch goal with MU : munch ?W ?m0 mx, ACC1 : accessible ?m0 ?q1 ?k, ACC2 : accessible ?m0 ?q2 ?k |- _ =>
        assert (ACC1m : accessible mx q1 k)
          by (eapply accessible_transport; [exact ACC1 | exact MU |];
              intros xq Hxq; destruct ACC1 as (? & ? & _); pose proof (sh_range_app xq ltac:(lia)) as SR;
              unfold AHI_LO in SR; rewrite ASHADOW_BASE_val in SR; cbn; lia);
        assert (ACC2m : accessible mx q2 k)
          by (eapply accessible_transport; [exact ACC2 | exact MU |];
              intros xq Hxq; destruct ACC2 as (? & ? & _); pose proof (sh_range_app xq ltac:(lia)) as SR;
              unfold AHI_LO in SR; rewrite ASHADOW_BASE_val in SR; cbn; lia) end
    end.

  (* [comment removed for export] *)
  Ltac shell_walk Ll Rr CTX FRAMESZ RK REALL :=
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?m _) =>
    lazymatch goal with ST0 : stk _ m ?Lo (bv_unsigned ?sp) |- _ =>
    pose proof (munch_refl [(bv_unsigned sp - FRAMESZ, bv_unsigned sp)] m) as MU;
    pose proof ST0 as ST; carve_frame 48%nat ST;
    do 8 zstep;
    zstep; call_pure asaninited_body; [eassumption .. |];
    let K0 := fresh "K0" in
    zstep; if_cases K0; [exfalso; revert K0; vm_compute; discriminate|];
    do 2 zstep;
    (* [comment removed for export] *)
    remember (Z_to_bv 64 CTX) as ctxw eqn:Hctxw;
    zstep;
    destruct (stk_split asegs _ _ (bv_unsigned sp + -48 - 16) _ ST ltac:(lia)) as [STlo SThi];
    zstep; call2 tryinit_body; try eassumption; rewrite ?unsigned_lit by lia; [exact SThi | unfold AHI_LO; lia |];
    try rewrite unsigned_lit in * by lia;
    match goal with Hhi : stk asegs ?mx (bv_unsigned sp + -48 - 16) (bv_unsigned sp + -48),
                    Hlo : stk asegs ?mx Lo (bv_unsigned sp + -48 - 16) |- _ =>
      pose proof (stk_merge asegs _ _ _ _ Hlo Hhi ltac:(lia)) as ST; clear Hlo Hhi end;
    do 2 zstep;
    let K1 := fresh "K1" in
    zstep; if_cases K1; [exfalso; revert K1; vm_compute; discriminate|];
    do 5 zstep;
    shell_consts;
    lazymatch goal with NA2 : bv_unsigned _ = _ |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    zstep; eapply evt_cut;
      [ eapply (mcc_body _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Ll Rr _ RK Lo);
        [ reflexivity | reflexivity | lia
        | first [ exact REALL | rewrite ?NA2; rewrite ?unsigned_lit by lia; first [eassumption | lia] ] .. ]
      | intros ms2 PO2; unfold real_post in PO2; zsimp_in PO2; revert ms2 PO2; post_call asegs mx ]
    end;
    do 6 zstep;
    lazymatch goal with FR : rw_cells _ ?mx (bv_unsigned sp + -48) _, STm : stk _ ?mx Lo (bv_unsigned sp + -48) |- _ =>
      release_frame FR STm (bv_unsigned sp) end;
    unfold real_post; finish
    end end.

